// 选协议版本下拉：走新接口 /prefund/superviseAgreeVersion/page
// 后端返回 regulatoryAgreementVId / theVersion（不是旧接口的 bbId）
initAgreementVersionOptions() {
  this.$post('/prefund/superviseAgreeVersion/page', { pageNum: 1, pageSize: 200 })
    .then((response) => {
      this.agreementVersionOptions = response.rows || []
      // 详情先到、字典后到时，回填版本名称
      if (this.form.regulatoryAgreementVId && !this.form.agreementVersion) {
        const matched = this.agreementVersionOptions.find(
          (item) => String(item.regulatoryAgreementVId) === String(this.form.regulatoryAgreementVId)
        )
        if (matched) {
          this.form.agreementVersion = matched.theVersion
        }
      }
    })
},

